wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm;

struct Node;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // Precondition from the contract: len(question) <= 512. It holds of
        // every input, so we rely on it rather than re-checking; the type system
        // and the upstream validator own that guarantee.

        let system = build_system(&ctx);
        let mut prompt = build_prompt(&ctx);

        // Bounded tool-orchestration loop. The model either answers (text) or
        // asks for a tool (call). The only tool this node can honour is the one
        // in its scope, `lookup`, backed by the read-only knowledge-base handle.
        const MAX_ROUNDS: usize = 4;
        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(&system, &prompt) {
                tool_llm::Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                tool_llm::Reply::Call(req) => {
                    if req.tool != "lookup" {
                        // Out-of-scope tool: we hold no import for it, so we
                        // cannot act on the request. Report, do not improvise.
                        return ResponseResult::Error(LlmError {
                            message: format!(
                                "model requested unavailable tool `{}`",
                                req.tool
                            ),
                        });
                    }
                    let results = kb_read::lookup(&req.query);
                    append_lookup_results(&mut prompt, &req.query, &results);
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool-orchestration loop did not converge".to_string(),
        })
    }
}

fn build_system(ctx: &ConversationContext) -> String {
    let intent = match ctx.intent {
        Intent::BillingQuestion => "a billing question",
        Intent::TechnicalSupport => "a technical-support request",
        Intent::AccountChange => "an account-change request",
        Intent::GeneralInquiry => "a general inquiry",
        Intent::Unknown => "an unclassified request",
    };
    format!(
        "You are a customer-support assistant handling {intent}. Answer the \
         user's question concisely and accurately. If you need facts from the \
         knowledge base, call the `lookup` tool before answering; otherwise \
         reply with the answer text."
    )
}

fn build_prompt(ctx: &ConversationContext) -> String {
    let mut prompt = String::new();
    prompt.push_str("Question:\n");
    prompt.push_str(&ctx.question);
    prompt.push('\n');

    if !ctx.knowledge.is_empty() {
        prompt.push_str("\nContext already gathered:\n");
        for k in &ctx.knowledge {
            prompt.push_str("- ");
            prompt.push_str(k);
            prompt.push('\n');
        }
    }
    prompt
}

fn append_lookup_results(prompt: &mut String, query: &str, results: &[String]) {
    prompt.push_str("\nResults of `lookup(\"");
    prompt.push_str(query);
    prompt.push_str("\")`:\n");
    if results.is_empty() {
        prompt.push_str("(no matching entries)\n");
    } else {
        for r in results {
            prompt.push_str("- ");
            prompt.push_str(r);
            prompt.push('\n');
        }
    }
    prompt.push_str("\nUse these results to answer, or call `lookup` again if \
                     you still need more.\n");
}

export!(Node);
```

